create table if not exists public.rounds (id bigint generated by default as identity primary key, course text not null, date date not null, players jsonb not null, created_at timestamptz default now());
alter table public.rounds enable row level security;
drop policy if exists "Anyone can view rounds" on public.rounds;
create policy "Anyone can view rounds" on public.rounds for select using (true);
-- Replace YOUR_ADMIN_USER_UUID with the UUID of your Supabase admin user before running the next policies.
drop policy if exists "Admin can insert rounds" on public.rounds;
create policy "Admin can insert rounds" on public.rounds for insert to authenticated with check (auth.uid() = '3b83b0f7-b1b4-4a49-9b34-9224d65972cc'::uuid);
drop policy if exists "Admin can update rounds" on public.rounds;
create policy "Admin can update rounds" on public.rounds for update to authenticated using (auth.uid() = '3b83b0f7-b1b4-4a49-9b34-9224d65972cc'::uuid) with check (auth.uid() = '3b83b0f7-b1b4-4a49-9b34-9224d65972cc'::uuid);
drop policy if exists "Admin can delete rounds" on public.rounds;
create policy "Admin can delete rounds" on public.rounds for delete to authenticated using (auth.uid() = '3b83b0f7-b1b4-4a49-9b34-9224d65972cc'::uuid);
